#!/bin/sh
# Name: Upsilon
# Author: Upsilon contributors
# Icon: data:image/png;base64,
# DontUseFBInk

# Scriptlet: tap "Upsilon" in the library to start the calculator.
# Needs the Universal Hotfix (Scriptlets support) and the upsilon folder
# installed at the root of the Kindle storage (/mnt/us/upsilon).

if [ ! -f /mnt/us/upsilon/bin/upsilon ]; then
    echo "Upsilon is not installed in /mnt/us/upsilon" >/mnt/us/upsilon-error.txt
    exit 1
fi
exec sh /mnt/us/upsilon/upsilon.sh --scriptlet
